package importjob

import "four-check-management-system/server/internal/inspection"

// PublishedTemplateTypeCodes lists the inspection types whose import workbook is
// generated by this package. Public dormitory hygiene stays excluded because its
// import entry is not approved yet, so it has no published template contract.
func PublishedTemplateTypeCodes() []string {
	return []string{
		inspection.InspectionTypeAttendance,
		inspection.InspectionTypeUnattended,
		inspection.InspectionTypeMorning,
		inspection.InspectionTypeLateReturn,
		inspection.InspectionTypeDormitoryHygiene,
		inspection.InspectionTypeClassroomHygiene,
		inspection.InspectionTypeEveningSelfStudy,
	}
}
